import{_ as r,o as t,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Purchase Orders Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Purchase Orders Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/purchase-orders-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Purchase Orders Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/purchase-orders-overview"}]]},"headers":[],"relativePath":"user-guide/purchase-orders-overview.md","filePath":"user-guide/purchase-orders-overview.md","lastUpdated":1786018214000}'),d={name:"user-guide/purchase-orders-overview.md"};function s(i,e,n,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="purchase-orders-module" tabindex="-1">Purchase Orders Module <a class="header-anchor" href="#purchase-orders-module" aria-label="Permalink to &quot;Purchase Orders Module&quot;">​</a></h1><p>Phase 4 Purchasing module (Milestone 2) on the frozen platform. Mirrors the <a href="/user-guide/estimates-overview">Estimates</a> reference architecture — a header + line-item document with a status workflow, assignment, notes, and an activity timeline. Purchase Orders hard-depends on the <strong>Vendors</strong> module (Milestone 1) — every purchase order must reference a vendor.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/purchase-orders">purchase-orders.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/purchase-orders">purchase-orders-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/purchase-orders">purchase-orders-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/estimates-overview">estimates.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-purchase-orders">../api/tenant-v1-purchase-orders.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Header: number (<code>PO-</code> prefix, configurable), required vendor, title, status, currency, order date, expected date, notes, subtotal/tax/total</li><li>Line items (description, quantity, unit price, tax rate, optional product) — subtotal/tax/total recomputed server-side, draft-only edits</li><li>Status workflow: <code>draft → sent → partially_received | received | cancelled</code> (also <code>sent → cancelled</code>, <code>partially_received → received | cancelled</code>)</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>purchase-orders.assign</code></li><li>Notes (comments) + activity timeline</li><li>Table view with search, status filter, assignee filter, and <strong>My Purchase Orders</strong> toggle</li><li>KPIs via <code>GET /purchase-orders/stats</code> (total, mine, draft, sent, partially received, received, cancelled)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:purchase-orders</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong>, hard-depends on <code>vendors</code></li><li>Audit + activity logging</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>purchase-orders.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>send</code> · <code>receive</code> · <code>cancel</code></p><p>Enable Purchase Orders from Marketplace (free) — Marketplace blocks the install until <strong>Vendors</strong> is already entitled. Catalog: slug <code>purchase-orders</code>, category <code>purchasing</code> (Purchasing), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 20</code>.</p><h2 id="receiving-and-inventory" tabindex="-1">Receiving and Inventory <a class="header-anchor" href="#receiving-and-inventory" aria-label="Permalink to &quot;Receiving and Inventory&quot;">​</a></h2><p><strong>Partially received</strong> remains a status-only acknowledgement. When Products and Inventory are entitled, marking an order <strong>received</strong> posts stock-in for each product-linked line whose Product tracks stock. Receiving may select an optional warehouse; the default warehouse is used otherwise. Lines without <code>product_id</code> do not post stock.</p><h2 id="convert-to-expense-soft-phase-4-milestone-3" tabindex="-1">Convert to expense (soft, Phase 4 Milestone 3) <a class="header-anchor" href="#convert-to-expense-soft-phase-4-milestone-3" aria-label="Permalink to &quot;Convert to expense (soft, Phase 4 Milestone 3)&quot;">​</a></h2><p>Sent, partially received, or received purchase orders can be converted to a draft <a href="/user-guide/expenses-overview">Expense</a> — a one-way, one-time action gated by the <code>purchase-orders.convert</code> permission and a <strong>soft</strong> entitlement check on the Expenses module (no hard <code>module_dependencies</code> row). See <a href="/user-guide/purchase-orders#convert-to-expense">Purchase Orders — User Guide</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Purchase order PDFs / e-mail delivery to vendors</li><li>Partial-quantity receiving per line item (status is currently header-level only)</li><li>Dashboard widgets for Purchase Orders</li></ul>',15)])])}const m=r(d,[["render",s]]);export{p as __pageData,m as default};
